const count = (flow.get('hj212_count') || 0) + 1;
flow.set('hj212_count', count);
const cn = String(msg.payload || '2011');
const now = new Date(Date.now() + 8 * 3600 * 1000);
const pad = n => String(n).padStart(2, '0');
const ms = String(now.getMilliseconds()).padStart(3, '0');
const stamp = `${now.getUTCFullYear()}${pad(now.getUTCMonth()+1)}${pad(now.getUTCDate())}${pad(now.getUTCHours())}${pad(now.getUTCMinutes())}${pad(now.getUTCSeconds())}`;
msg.hj212 = {
  QN: stamp + ms,
  ST: flow.get('hj212_st') || '31',
  CN: cn,
  PW: flow.get('hj212_pw') || '123456',
  MN: flow.get('hj212_mn') || '88888880000001',
  Flag: '5',
  DataTime: stamp,
  factors: {
    'a21026': {Rtd: (35 + Math.sin(count / 3) * 5).toFixed(2), Flag: 'N'},
    'a21002': {Rtd: (48 + Math.cos(count / 4) * 6).toFixed(2), Flag: 'N'},
    'a34013': {Rtd: (8 + Math.random() * 3).toFixed(2), Flag: 'N'},
    'a01012': {Rtd: (82 + Math.random() * 8).toFixed(2), Flag: 'N'}
  }
};
node.status({fill:'blue', shape:'dot', text:`CN=${cn} ${Object.keys(msg.hj212.factors).length}因子`});
return msg;

function crc16HJ212(str) {
  let crc = 0xffff;
  const buf = Buffer.from(str, 'utf8');
  for (const b of buf) {
    crc ^= b;
    for (let i = 0; i < 8; i++) {
      crc = (crc & 1) ? ((crc >> 1) ^ 0xA001) : (crc >> 1);
      crc &= 0xffff;
    }
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}
const h = msg.hj212;
const cpItems = [`DataTime=${h.DataTime}`];
for (const [factor, item] of Object.entries(h.factors)) {
  const fields = [];
  for (const [k, v] of Object.entries(item)) fields.push(`${factor}-${k}=${v}`);
  cpItems.push(fields.join(','));
}
const data = [
  `QN=${h.QN}`,
  `ST=${h.ST}`,
  `CN=${h.CN}`,
  `PW=${h.PW}`,
  `MN=${h.MN}`,
  `Flag=${h.Flag}`,
  `CP=&&${cpItems.join(';')}&&`
].join(';');
const len = Buffer.byteLength(data, 'utf8').toString().padStart(4, '0');
const crc = crc16HJ212(data);
msg.payload = `##${len}${data}${crc}\r\n`;
msg.hj212Frame = msg.payload;
msg.headers = {'Content-Type':'text/plain; charset=utf-8'};
msg.url = (flow.get('hj212_baseUrl') || 'http://127.0.0.1:5905') + '/api/hj212/upload';
node.status({fill:'green', shape:'dot', text:`len=${len} crc=${crc}`});
return msg;

function crc16HJ212(str) {
  let crc = 0xffff;
  for (const b of Buffer.from(str, 'utf8')) {
    crc ^= b;
    for (let i = 0; i < 8; i++) {
      crc = (crc & 1) ? ((crc >> 1) ^ 0xA001) : (crc >> 1);
      crc &= 0xffff;
    }
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}
const raw = String(msg.payload).trim();
if (!raw.startsWith('##')) throw new Error('不是 HJ212 报文');
const len = Number(raw.slice(2, 6));
const data = raw.slice(6, 6 + len);
const crcGiven = raw.slice(6 + len, 10 + len).toUpperCase();
const crcCalc = crc16HJ212(data);
const cpMatch = data.match(/CP=&&([\s\S]*)&&/);
const cpRaw = cpMatch ? cpMatch[1] : '';
const headerText = data.replace(/CP=&&[\s\S]*&&/, 'CP=__CP__');
const header = {};
for (const part of headerText.split(';')) {
  const i = part.indexOf('=');
  if (i > 0) header[part.slice(0, i)] = part.slice(i + 1);
}
delete header.CP;
const cp = {};
const factors = {};
for (const group of cpRaw.split(';')) {
  if (!group) continue;
  for (const item of group.split(',')) {
    const i = item.indexOf('=');
    if (i < 0) continue;
    const k = item.slice(0, i), v = item.slice(i + 1);
    const dash = k.indexOf('-');
    if (dash < 0) cp[k] = v;
    else {
      const factor = k.slice(0, dash), field = k.slice(dash + 1);
      factors[factor] = factors[factor] || {};
      factors[factor][field] = v;
    }
  }
}
cp.factors = factors;
msg.payload = {length: len, crc_given: crcGiven, crc_calc: crcCalc, crc_ok: crcGiven === crcCalc, header, cp};
node.status({fill: msg.payload.crc_ok ? 'green' : 'red', shape:'dot', text:'crc=' + msg.payload.crc_ok});
return msg;
